from collections import deque

def isBipartite(self, graph: list[list[int]]) -> bool:
    n = len(graph)
    color = [-1] * n  # -1 = uncolored
    for start in range(n):
        if color[start] != -1:
            continue
        color[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1   # opposite side
                    q.append(v)
                elif color[v] == color[u]:
                    return False              # same-side clash
    return True

