private int[] color;

public boolean isBipartite(int[][] graph) {
    int n = graph.length;
    color = new int[n];
    Arrays.fill(color, -1);
    for (int i = 0; i < n; i++) {
        if (color[i] == -1 && !dfs(graph, i, 0)) {
            return false;
        }
    }
    return true;
}

private boolean dfs(int[][] graph, int u, int c) {
    color[u] = c;
    for (int v : graph[u]) {
        if (color[v] == -1) {
            if (!dfs(graph, v, c ^ 1)) return false;
        } else if (color[v] == c) {
            return false; // neighbor on the same side
        }
    }
    return true;
}

